Matching Ayahs
- = الف، لام، میم۔ 2:1; 3:1; 29:1; 30:1; 31:1; 32:1
- = یہی لوگ اپنے رب کی طرف سے ہدایت پر ہیں، اور یہی لوگ کامیاب ہیں۔ 2:5; 31:5
- = اے بنی اسرائیل! میری اس نعمت کو یاد کرو جو میں نے تم پر کی، اور یہ کہ میں نے تمہیں تمام جہانوں (لوگوں) پر فضیلت دی۔ 2:47; 2:122
- = وہ ایک امت تھی جو گزر چکی۔ ان کے لیے وہ ہے جو انہوں نے کمایا، اور تمہارے لیے وہ ہے جو تم نے کمایا۔ اور تم سے ان کے اعمال کے بارے میں پوچھ نہیں ہوگی۔ 2:134; 2:141
- = وہ اس میں ہمیشہ رہیں گے۔ ان سے عذاب ہلکا نہیں کیا جائے گا اور نہ انہیں مہلت دی جائے گی۔ 2:162; 3:88
- = مگر جو اس کے بعد توبہ کر لیں اور خود کو سنوار لیں۔ بیشک اللہ بڑا معاف فرمانے والا، نہایت رحم فرمانے والا ہے۔ 3:89; 24:5
- = اور جنہوں نے کفر کیا اور ہماری آیتوں کو جھٹلایا – وہی لوگ دوزخ کے باشندے ہیں۔ 5:10; 5:86
- = اور ان کے رب کی نشانیوں میں سے کوئی نشانی ان کے پاس آتی ہے تو وہ اس سے منہ موڑ لیتے ہیں۔ 6:4; 36:46
- = اور آپ سے پہلے بھی رسولوں کا مذاق اڑایا گیا، مگر جن لوگوں نے مذاق کیا انہیں اسی چیز نے گھیر لیا جس کا وہ مذاق اڑاتے تھے۔ 6:10; 21:41
