- ابراہیم، اسماعیل، اسحاق، یعقوب اور ان کی اولاد، اور جو موسیٰ اور عیسیٰ کو دیا گیا۔ (إِبْرَاهِيمَ وَإِسْمَاعِيلَ وَإِسْحَاقَ وَيَعْقُوبَ وَالْأَسْبَاطِ وَمَا أُوتِيَ مُوسَى وَعِيسَى) 2:136; 3:84
