- اللہ تمہیں تمہاری قسموں میں لغو (بےمعنی) باتوں پر نہیں پکڑے گا، لیکن تمہیں پکڑے گا اس پر جو۔ (لَّا يُؤَاخِذُكُمُ اللَّهُ بِاللَّغْوِ فِي أَيْمَانِكُمْ وَلَكِن يُؤَاخِذُكُم بِمَا) 2:225; 5:89
- رحمت، وہ اس پر خوش ہوئے، اور اگر انہیں ان کے ہاتھوں کی کمائی کی وجہ سے کوئی برائی پہنچتی ہے۔ (رَحْمَةً فَرِحُوا بِهَا وَإِن تُصِبْهُمْ سَيِّئَةٌ بِمَا قَدَّمَتْ أَيْدِيهِمْ) 30:36; 42:48
- جن کے نیچے نہریں بہتی ہیں، وہ ان میں ہمیشہ رہیں گے، اور عمل کرنے والوں کا کیا ہی اچھا اجر ہے! (تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا وَنِعْمَ أَجْرُ الْعَامِلِينَ) 3:136; 29:58
- اللہ جانتا ہے جو کچھ آسمانوں اور زمین میں ہے، اور اللہ۔ (اللَّهُ وَيَعْلَمُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَاللَّهُ) 3:29; 49:16
- اللہ کی اطاعت کرو اور رسول کی اطاعت کرو، پھر اگر تم منہ موڑو تو اس پر (فرض) صرف۔ (أَطِيعُوا اللَّهَ وَأَطِيعُوا الرَّسُولَ فَإِن تَوَلَّوْا فَإِنَّمَا عَلَيْهِ) 24:54; 64:12
- ان کا اجر ان کے رب کے پاس ہے، نہ انہیں کوئی خوف اور نہ وہ۔ (فَلَهُمْ أَجْرُهُمْ عِندَ رَبِّهِمْ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ) 2:274; 2:277
- اور انہوں نے کہا: کیا جب ہم ہڈیاں اور ریزہ ریزہ ہو جائیں گے تو کیا ہم نئی تخلیق میں اٹھائے جائیں گے؟ (وَقَالُوا أَإِذَا كُنَّا عِظَامًا وَرُفَاتًا أَإِنَّا لَمَبْعُوثُونَ خَلْقًا جَدِيدًا) 17:49; 17:98
- اور وہ اپنے لیے اللہ کے سوا کوئی ولی اور نہ کوئی مددگار پائیں گے۔ (وَلَا يَجِدُونَ لَهُم مِّن دُونِ اللَّهِ وَلِيًّا وَلَا نَصِيرًا) 4:173; 33:17
- تم کتنی دیر ٹھہرے؟ اس نے کہا: ایک دن یا ایک دن کا کچھ حصہ ٹھہرا ہوں۔ اس نے کہا: (كَمْ لَبِثْتَ قَالَ لَبِثْتُ يَوْمًا أَوْ بَعْضَ يَوْمٍ قَالَ) 2:259; 18:19
- ہمیشہ قیامت کے دن تک۔ کون ہے اللہ کے سوا کوئی معبود جو تمہیں (یہ) لا سکے؟ (سَرْمَدًا إِلَى يَوْمِ الْقِيَامَةِ مَنْ إِلَهٌ غَيْرُ اللَّهِ يَأْتِيكُم) 28:71; 28:72
- جو نیک عمل کرے خواہ مرد ہو یا عورت اور وہ مومن ہو۔ (مَنْ عَمِلَ صَالِحًا مِّن ذَكَرٍ أَوْ أُنثَى وَهُوَ مُؤْمِنٌ) 16:97; 40:40
- جو لوگ اللہ کی راہ سے روکتے ہیں اور اسے ٹیڑھا کرنا چاہتے ہیں اور آخرت کا انکار کرتے ہیں۔ (الَّذِينَ يَصُدُّونَ عَن سَبِيلِ اللَّهِ وَيَبْغُونَهَا عِوَجًا وَهُم بِالْآخِرَةِ) 7:45; 11:19
- جہاں چاہو (کھاؤ) اور اس درخت کے قریب نہ جانا ورنہ تم ظالموں میں سے ہو جاؤ گے۔ (حَيْثُ شِئْتُمَا وَلَا تَقْرَبَا هَذِهِ الشَّجَرَةَ فَتَكُونَا مِنَ الظَّالِمِينَ) 2:35; 7:19
- کہہ دو: اے میری قوم! تم اپنی جگہ عمل کرو، میں بھی عمل کرتا ہوں، عنقریب تم جان لو گے۔ (قُلْ يَاقَوْمِ اعْمَلُوا عَلَى مَكَانَتِكُمْ إِنِّي عَامِلٌ فَسَوْفَ تَعْلَمُونَ) 6:135; 39:39
- بےشک نقصان اٹھانے والے وہ ہیں جنہوں نے قیامت کے دن اپنے آپ کو اور اپنے گھر والوں کو نقصان میں ڈالا۔ خبردار! (إِنَّ الْخَاسِرِينَ الَّذِينَ خَسِرُوا أَنفُسَهُمْ وَأَهْلِيهِمْ يَوْمَ الْقِيَامَةِ أَلَا) 39:15; 42:45
- جو ہدایت پاتا ہے تو اپنے فائدے کے لیے پاتا ہے اور جو بھٹکتا ہے تو اپنے نقصان کے لیے بھٹکتا ہے، اور کوئی۔ (يَهْتَدِي لِنَفْسِهِ وَمَن ضَلَّ فَإِنَّمَا يَضِلُّ عَلَيْهَا وَمَا) 10:108; 39:41
- اور کافر کہتے ہیں: اس پر اس کے رب کی طرف سے کوئی نشانی کیوں نہ اتاری گئی؟ (وَيَقُولُ الَّذِينَ كَفَرُوا لَوْلَا أُنزِلَ عَلَيْهِ آيَةٌ مِّن رَّبِّهِ) 13:7; 13:27
- جس نے تمہارے لیے رات بنائی تاکہ تم اس میں سکون کرو اور دن کو روشن (بنایا)۔ بےشک۔ (الَّذِي جَعَلَ لَكُمُ اللَّيْلَ لِتَسْكُنُوا فِيهِ وَالنَّهَارَ مُبْصِرًا إِنَّ) 10:67; 40:61
- اس دن کے آنے سے پہلے جس میں نہ کوئی خرید و فروخت ہو اور نہ کوئی (دوستی)۔ (مِّن قَبْلِ أَن يَأْتِيَ يَوْمٌ لَّا بَيْعٌ فِيهِ وَلَا) 2:254; 14:31
- تاکہ وہ غور کریں، ان کے ساتھی کو کوئی جنون نہیں، وہ تو صرف ایک ڈرانے والا ہے۔ (يَتَفَكَّرُوا مَا بِصَاحِبِهِم مِّن جِنَّةٍ إِنْ هُوَ إِلَّا نَذِيرٌ) 7:184; 34:46
- وہ ان میں ہمیشہ رہیں گے، نہ ان سے عذاب ہلکا کیا جائے گا اور نہ انہیں مہلت دی جائے گی۔ (خَالِدِينَ فِيهَا لَا يُخَفَّفُ عَنْهُمُ الْعَذَابُ وَلَا هُمْ يُنظَرُونَ) 2:162; 3:88
- اپنی نگاہیں اس چیز پر نہ دوڑا جو ہم نے ان میں سے بعض کو عارضی فائدہ دیا ہے۔ (لَا تَمُدَّنَّ عَيْنَيْكَ إِلَى مَا مَتَّعْنَا بِهِ أَزْوَاجًا مِّنْهُمْ) 15:88; 20:131
- اور لوگوں کو ان کی چیزیں کم نہ دو اور زمین میں فساد نہ پھیلاؤ۔ (وَلَا تَبْخَسُوا النَّاسَ أَشْيَاءَهُمْ وَلَا تَعْثَوْا فِي الْأَرْضِ مُفْسِدِينَ) 11:85; 26:183
- اور اس پر سلام ہے جس دن وہ پیدا ہوا، جس دن مرے گا اور جس دن زندہ اٹھایا جائے گا۔ (وَسَلَامٌ عَلَيْهِ يَوْمَ وُلِدَ وَيَوْمَ يَمُوتُ وَيَوْمَ يُبْعَثُ حَيًّا) 19:15; 19:33
- اے میری قوم! تم اپنی جگہ عمل کرو، میں بھی عمل کرتا ہوں، عنقریب تم جان لو گے کہ کون۔ (يَاقَوْمِ اعْمَلُوا عَلَى مَكَانَتِكُمْ إِنِّي عَامِلٌ فَسَوْفَ تَعْلَمُونَ مَن) 6:135; 11:93
- اور کسی رسول کو یہ حق نہیں کہ وہ اللہ کی اجازت کے بغیر کوئی نشانی لے آئے۔ (وَمَا كَانَ لِرَسُولٍ أَن يَأْتِيَ بِآيَةٍ إِلَّا بِإِذْنِ اللَّهِ) 13:38; 40:78
- پھر ہر شخص کو اس کی کمائی کا پورا پورا بدلہ دیا جائے گا اور ان پر ظلم نہیں کیا جائے گا۔ (ثُمَّ تُوَفَّى كُلُّ نَفْسٍ مَّا كَسَبَتْ وَهُمْ لَا يُظْلَمُونَ) 2:281; 3:161
- خواہ مرد ہو یا عورت اور وہ مومن ہو – یہی لوگ جنت میں داخل ہوں گے۔ (مِن ذَكَرٍ أَوْ أُنثَى وَهُوَ مُؤْمِنٌ فَأُولَئِكَ يَدْخُلُونَ الْجَنَّةَ) 4:124; 40:40
- اس نے کوئی اولاد نہیں رکھی اور نہ بادشاہت میں اس کا کوئی شریک ہے۔ (لَمْ يَتَّخِذْ وَلَدًا وَلَمْ يَكُن لَّهُ شَرِيكٌ فِي الْمُلْكِ) 17:111; 25:2
- اللہ جسے ہدایت دے وہی ہدایت یافتہ ہے اور جسے گمراہ کرے اس کے لیے تم کوئی ولی نہ پاؤ گے۔ (وَمَن يَهْدِ اللَّهُ فَهُوَ الْمُهْتَدِ وَمَن يُضْلِلْ فَلَن تَجِدَ) 17:97; 18:17
- دیکھو وہ تمہیں کیسی کیسی مثالیں دیتے ہیں، پس وہ بھٹک گئے اور راستہ نہیں پا سکتے۔ (انظُرْ كَيْفَ ضَرَبُوا لَكَ الْأَمْثَالَ فَضَلُّوا فَلَا يَسْتَطِيعُونَ سَبِيلًا) 17:48; 25:9
- کہہ دو: میں ڈرتا ہوں اگر میں اپنے رب کی نافرمانی کروں تو ایک بڑے دن کے عذاب سے۔ (قُلْ إِنِّي أَخَافُ إِنْ عَصَيْتُ رَبِّي عَذَابَ يَوْمٍ عَظِيمٍ) 6:15; 39:13
- ان کی شرمگاہیں کھل گئیں اور وہ جنت کے پتوں سے اپنے اوپر چپکنے لگے۔ (بَدَتْ لَهُمَا سَوْآتُهُمَا وَطَفِقَا يَخْصِفَانِ عَلَيْهِمَا مِن وَرَقِ الْجَنَّةِ) 7:22; 20:121
- اور تم اپنی قدرت کے مطابق اللہ کے سوا جنہیں پکار سکتے ہو پکار لو، اگر تم سچے ہو۔ (وَادْعُوا مَنِ اسْتَطَعْتُم مِّن دُونِ اللَّهِ إِن كُنتُمْ صَادِقِينَ) 10:38; 11:13
- وہ سب کچھ جو زمین میں ہے اور اس کے ساتھ اتنا ہی اور، تاکہ وہ اس کے ذریعے خود کو چھڑا سکیں۔ (مَّا فِي الْأَرْضِ جَمِيعًا وَمِثْلَهُ مَعَهُ لِيَفْتَدُوا بِهِ مِنْ) 5:36; 39:47
- جو ہم نے تمہیں دیا ہے اسے مضبوطی سے پکڑو اور جو اس میں ہے اسے یاد رکھو – شاید تم ڈرو۔ (خُذُوا مَا آتَيْنَاكُم بِقُوَّةٍ وَاذْكُرُوا مَا فِيهِ لَعَلَّكُمْ تَتَّقُونَ) 2:63; 7:171
- کیا تم وہ فحش کام کرتے ہو جو تم سے پہلے جہان والوں میں سے کسی نے نہیں کیا؟ (أَتَأْتُونَ الْفَاحِشَةَ مَا سَبَقَكُم بِهَا مِنْ أَحَدٍ مِّنَ الْعَالَمِينَ) 7:80; 29:28
- آسمانوں اور زمین میں جو کچھ ہے سب اللہ کا ہے اور اللہ (ہر چیز کا) احاطہ کیے ہوئے ہے۔ (وَلِلَّهِ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَكَانَ اللَّهُ) 4:126; 4:131
- ان کے اعمال کی برائیاں ان پر آ پڑیں اور جس چیز کا وہ مذاق اڑاتے تھے اس نے انہیں گھیر لیا۔ (سَيِّئَاتُ مَا عَمِلُوا وَحَاقَ بِهِم مَّا كَانُوا بِهِ يَسْتَهْزِئُونَ) 16:34; 45:33
- تم میں سے ایک رسول جو تمہیں ہماری آیات پڑھ کر سنائے، تمہیں پاک کرے اور تمہیں کتاب و حکمت سکھائے۔ (رَسُولًا مِّنكُمْ يَتْلُو عَلَيْكُمْ آيَاتِنَا وَيُزَكِّيكُمْ وَيُعَلِّمُكُمُ الْكِتَابَ وَالْحِكْمَةَ) 2:151; 62:2
- اس سے بارہ چشمے پھوٹ نکلے، ہر قوم نے اپنا پانی پینے کی جگہ معلوم کر لی۔ (مِنْهُ اثْنَتَا عَشْرَةَ عَيْنًا قَدْ عَلِمَ كُلُّ أُنَاسٍ مَّشْرَبَهُمْ) 2:60; 7:160
- مگر گمان، بےشک گمان حق کے مقابلے میں کچھ فائدہ نہیں دیتا۔ (إِلَّا ظَنًّا إِنَّ الظَّنَّ لَا يُغْنِي مِنَ الْحَقِّ شَيْئًا) 10:36; 53:28
- پھر جب میں اسے درست کر لوں اور اس میں اپنی روح پھونک دوں تو تم اس کے سامنے سجدے میں گر پڑنا۔ (فَإِذَا سَوَّيْتُهُ وَنَفَخْتُ فِيهِ مِن رُّوحِي فَقَعُوا لَهُ سَاجِدِينَ) 15:29; 38:72
- گھر (آخرت) کا انجام کس کے لیے ہے؟ بےشک ظالم کامیاب نہیں ہوں گے۔ (مَن تَكُونُ لَهُ عَاقِبَةُ الدَّارِ إِنَّهُ لَا يُفْلِحُ الظَّالِمُونَ) 6:135; 28:37
- جس نے آسمانوں اور زمین کو پیدا کیا، وہ ان جیسا پیدا کرنے پر قادر ہے۔ (الَّذِي خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ قَادِرٌ عَلَى أَن يَخْلُقَ مِثْلَهُمْ) 17:99; 36:81
- مومن مردوں اور مومن عورتوں کے لیے – جنتوں کے نیچے نہریں بہتی ہیں، وہ ان میں ہمیشہ رہیں گے۔ (الْمُؤْمِنِينَ وَالْمُؤْمِنَاتِ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا) 9:72; 48:5
