- ہر نفس کو اس کی کمائی کا پورا پورا بدلہ دیا جائے گا اور ان پر ظلم نہیں کیا جائے گا۔ (تُوَفَّى كُلُّ نَفْسٍ مَّا كَسَبَتْ وَهُمْ لَا يُظْلَمُونَ) 2:281; 3:25; 3:161
- اور اس جان کو قتل نہ کرو جسے اللہ نے حرام کیا ہے، مگر حق کے ساتھ۔ (وَلَا تَقْتُلُوا النَّفْسَ الَّتِي حَرَّمَ اللَّهُ إِلَّا بِالْحَقِّ) 6:151; 17:33; 25:68
- جب وہ کسی کام کا فیصلہ کرتا ہے تو اسے کہتا ہے: "ہو جا۔" (إِذَا قَضَى أَمْرًا فَإِنَّمَا يَقُولُ لَهُ كُن) 3:47; 19:35; 40:68
- جہنم کے دروازوں میں داخل ہو جاؤ، وہاں ہمیشہ رہو گے، اور تکبر کرنے والوں کا ٹھکانا کتنا برا ہے! (فَادْخُلُوا أَبْوَابَ جَهَنَّمَ خَالِدِينَ فِيهَا فَلَبِئْسَ مَثْوَى الْمُتَكَبِّرِينَ) 16:29; 39:72; 40:76
- کیا تم نے ان لوگوں کو نہیں دیکھا جنہیں کتاب کا کچھ حصہ دیا گیا؟ (أَلَمْ تَرَ إِلَى الَّذِينَ أُوتُوا نَصِيبًا مِّنَ الْكِتَابِ) 3:23; 4:44; 4:51
- ان کے لیے جنتیں ہیں جن کے نیچے نہریں بہتی ہیں، وہاں وہ ہمیشہ رہیں گے۔ (لَهُمْ جَنَّاتٌ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا) 3:198; 5:119; 9:89
- اے میری قوم! تم اپنی جگہ عمل کرتے رہو، میں بھی عمل کر رہا ہوں، عنقریب تم جان لو گے۔ (يَاقَوْمِ اعْمَلُوا عَلَى مَكَانَتِكُمْ إِنِّي عَامِلٌ فَسَوْفَ تَعْلَمُونَ) 6:135; 11:93; 39:39
- جو اللہ اور اس کے رسول کی مخالفت کرے تو اس کے لیے جہنم کی آگ ہے، وہاں وہ ہمیشہ رہے گا۔ (اللَّهَ وَرَسُولَهُ فَأَنَّ لَهُ نَارَ جَهَنَّمَ خَالِدًا فِيهَا) 9:63; 72:23
- ان کے دلوں پر پردے ہیں تاکہ وہ اسے نہ سمجھیں، اور ان کے کانوں میں گرانی ہے۔ (عَلَى قُلُوبِهِمْ أَكِنَّةً أَن يَفْقَهُوهُ وَفِي آذَانِهِمْ وَقْرًا) 17:46; 18:57
- جس بستی میں کوئی ڈرانے والا آیا، اس کے آسائش والوں نے کہا: "ہم..." (فِي قَرْيَةٍ مِّن نَّذِيرٍ إِلَّا قَالَ مُتْرَفُوهَا إِنَّا) 34:34; 43:23
- انہوں نے کہا: "ہمارے لیے اپنے رب سے دعا کرو کہ وہ ہمیں واضح کرے کہ وہ کیا ہے؟" (قَالُوا ادْعُ لَنَا رَبَّكَ يُبَيِّن لَّنَا مَا هِيَ) 2:68; 2:70
- وہ کہیں گے: "اللہ" کہہ دو: "سب تعریف اللہ کے لیے ہے!" لیکن ان میں اکثر... (لَيَقُولُنَّ اللَّهُ قُلِ الْحَمْدُ لِلَّهِ بَلْ أَكْثَرُهُمْ لَا) 29:63; 31:25
- اور اس کی قوم کا جواب اس کے سوا کچھ نہ تھا کہ انہوں نے کہا: "انہیں نکال دو..." (وَمَا كَانَ جَوَابَ قَوْمِهِ إِلَّا أَن قَالُوا أَخْرِجُوهُم) 7:82; 27:56
- ان کے نیچے نہریں بہتی ہیں، وہاں وہ ہمیشہ رہیں گے۔ یہی بڑی کامیابی ہے۔ (تَحْتَهَا الْأَنْهَارُ خَالِدِينَ فِيهَا أَبَدًا ذَلِكَ الْفَوْزُ الْعَظِيمُ) 9:100; 64:9
- یہی لوگ اپنے رب کی طرف سے ہدایت پر ہیں اور یہی کامیاب ہیں۔ (أُولَئِكَ عَلَى هُدًى مِّن رَّبِّهِمْ وَأُولَئِكَ هُمُ الْمُفْلِحُونَ) 2:5; 31:5
- جس پر ذلت آمیز عذاب آئے اور جس پر دائمی عذاب طاری ہو۔ (مَن يَأْتِيهِ عَذَابٌ يُخْزِيهِ وَيَحِلُّ عَلَيْهِ عَذَابٌ مُّقِيمٌ) 11:39; 39:40
- زمین میں چلو پھرو اور دیکھو کہ جھٹلانے والوں کا انجام کیسا ہوا۔ (فَسِيرُوا فِي الْأَرْضِ فَانظُرُوا كَيْفَ كَانَ عَاقِبَةُ الْمُكَذِّبِينَ) 3:137; 16:36
- وہ اسے کبھی بھی آرزو نہیں کریں گے، اس وجہ سے جو ان کے ہاتھوں نے آگے بھیجا ہے۔ اور اللہ ظالموں کو خوب جانتا ہے۔ (يَتَمَنَّوْهُ أَبَدًا بِمَا قَدَّمَتْ أَيْدِيهِمْ وَاللَّهُ عَلِيمٌ بِالظَّالِمِينَ) 2:95; 62:7
- وہ خوب جانتا ہے کہ اس کی راہ سے کون بھٹکا، اور وہ خوب جانتا ہے... (هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ وَهُوَ أَعْلَمُ) 53:30; 68:7
- بے شک اللہ میرا رب ہے اور تمہارا رب، سو تم اس کی عبادت کرو۔ یہی سیدھا راستہ ہے۔ (إِنَّ اللَّهَ رَبِّي وَرَبُّكُمْ فَاعْبُدُوهُ هَذَا صِرَاطٌ مُّسْتَقِيمٌ) 3:51; 19:36
- لوگوں پر فضل والا ہے، لیکن ان میں اکثر شکر نہیں کرتے۔ (لَذُو فَضْلٍ عَلَى النَّاسِ وَلَكِنَّ أَكْثَرَهُمْ لَا يَشْكُرُونَ) 10:60; 27:73
- آسمانوں اور زمین اور ان کے درمیان کی چیزوں کو، حق اور ایک مقررہ مدت کے ساتھ (پیدا کیا)۔ (السَّمَاوَاتِ وَالْأَرْضَ وَمَا بَيْنَهُمَا إِلَّا بِالْحَقِّ وَأَجَلٍ مُّسَمًّى) 30:8; 46:3
- انہیں چھوڑ دو کہ وہ اپنی باتیوں اور کھیل میں پڑے رہیں یہاں تک کہ اپنے اس دن سے جا ملیں جس کا ان سے وعدہ کیا گیا ہے۔ (فَذَرْهُمْ يَخُوضُوا وَيَلْعَبُوا حَتَّى يُلَاقُوا يَوْمَهُمُ الَّذِي يُوعَدُونَ) 43:83; 70:42
- اور جب ایمان والوں سے ملتے ہیں تو کہتے ہیں: "ہم ایمان لائے،" اور جب تنہا ہوتے ہیں تو... (وَإِذَا لَقُوا الَّذِينَ آمَنُوا قَالُوا آمَنَّا وَإِذَا خَلَوْا) 2:14; 2:76
- انہوں نے تورات اور انجیل کو اور جو کچھ ان کے رب کی طرف سے ان پر نازل کیا گیا تھا، قائم رکھا۔ (أَقَامُوا التَّوْرَاةَ وَالْإِنجِيلَ وَمَا أُنزِلَ إِلَيْهِم مِّن رَّبِّهِمْ) 5:66; 5:68
- وہ جانتا ہے جو کچھ ان کے سامنے ہے اور جو کچھ ان کے پیچھے ہے، اور وہ اس کا احاطہ نہیں کر سکتے... (يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَلَا يُحِيطُونَ) 2:255; 20:110
- اور وہی ہے جس نے آسمانوں اور زمین کو چھ دنوں میں پیدا کیا۔ (وَهُوَ الَّذِي خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ فِي سِتَّةِ أَيَّامٍ) 11:7; 57:4
- بے شک اس میں تمہارے لیے ایک نشانی ہے، اگر تم ایمان رکھتے ہو۔ (إِنَّ فِي ذَلِكَ لَآيَةً لَّكُمْ إِن كُنتُم مُّؤْمِنِينَ) 2:248; 3:49
- اور لوگوں کو کس چیز نے روکا کہ ایمان لائیں جب ان کے پاس ہدایت آگئی؟ (وَمَا مَنَعَ النَّاسَ أَن يُؤْمِنُوا إِذْ جَاءَهُمُ الْهُدَى) 17:94; 18:55
- انہوں نے اللہ کے شریک ٹھہرائے تاکہ اس کی راہ سے گمراہ کریں۔ کہہ دو: "مزے کرو..." (وَجَعَلُوا لِلَّهِ أَندَادًا لِّيُضِلُّوا عَن سَبِيلِهِ قُلْ تَمَتَّعُوا) 14:30; 39:8
- اور وہ اس بات پر حیران ہوئے کہ ان کے پاس خود انہی میں سے ایک ڈرانے والا آیا، اور کافروں نے کہا: "یہ..." (وَعَجِبُوا أَن جَاءَهُم مُّنذِرٌ مِّنْهُمْ وَقَالَ الْكَافِرُونَ هَذَا) 38:4; 50:2
- بے شک تمہارا رب خوب جانتا ہے کہ اس کی راہ سے کون بھٹکا ہے۔ (إِنَّ رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ) 53:30; 68:7
- اس شخص کی طرح جو اپنا مال لوگوں کو دکھانے کے لیے خرچ کرتا ہے اور اللہ پر ایمان نہیں رکھتا۔ (كَالَّذِي يُنفِقُ مَالَهُ رِئَاءَ النَّاسِ وَلَا يُؤْمِنُ بِاللَّهِ) 2:264; 4:38
- اس میں سے جو ہم نے تمہیں دیا ہے، خرچ کرو اس سے پہلے کہ... آئے۔ (أَنفِقُوا مِمَّا رَزَقْنَاكُم مِّن قَبْلِ أَن يَأْتِيَ) 2:254; 63:10
- اس نے تمہارے لیے جو کچھ آسمانوں میں ہے اور جو کچھ زمین میں ہے سب کو مسخر کر دیا۔ (سَخَّرَ لَكُم مَّا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ) 31:20; 45:13
- اور بے شک ہم اس چیز کے بارے میں شک میں ہیں جس کی طرف تم ہمیں بلا رہے ہو۔ (وَإِنَّنَا لَفِي شَكٍّ مِّمَّا تَدْعُونَا إِلَيْهِ مُرِيبٍ) 11:62; 14:9
- بے شک تمہارا رب رزق کو جسے چاہے کشادہ کرتا ہے اور تنگ کرتا ہے، بے شک وہ... (إِنَّ رَبَّكَ يَبْسُطُ الرِّزْقَ لِمَن يَشَاءُ وَيَقْدِرُ إِنَّهُ) 17:30; 34:36
- آسمانوں اور زمین اور ان کے درمیان کی چیزوں کا رب، اگر تم یقین رکھنے والے ہو۔ (رَبُّ السَّمَاوَاتِ وَالْأَرْضِ وَمَا بَيْنَهُمَا إِن كُنتُم مُّوقِنِينَ) 26:24; 44:7
- ہم اللہ پر ایمان لائے اور جو ہم پر نازل ہوا اور جو ... پر نازل ہوا۔ (آمَنَّا بِاللَّهِ وَمَا أُنزِلَ إِلَيْنَا وَمَا أُنزِلَ إِلَى) 2:136; 3:199
- اور ظالموں کو چنگھاڑ نے آ پکڑا، اور وہ اپنے گھروں میں اوندھے منہ پڑے رہ گئے۔ (وَأَخَذَ الَّذِينَ ظَلَمُوا الصَّيْحَةُ فَأَصْبَحُوا فِي دِيَارِهِمْ جَاثِمِينَ) 11:67; 11:94
- پس تم پر کوئی گناہ نہیں اس میں جو وہ اپنے بارے میں کریں۔ (فَلَا جُنَاحَ عَلَيْكُمْ فِيمَا فَعَلْنَ فِي أَنفُسِهِنَّ) 2:234; 2:240
- تمہارا رب خوب جانتا ہے کہ اس کی راہ سے کون بھٹکا، اور وہ... (رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ وَهُوَ) 53:30; 68:7
- اپنے حکم سے روح کو جس پر چاہے اپنے بندوں میں سے نازل کرتا ہے۔ (بِالرُّوحِ مِنْ أَمْرِهِ عَلَى مَن يَشَاءُ مِنْ عِبَادِهِ) 16:2; 40:15
- اور ہم نے عیسیٰ بن مریم کو روشن نشانیاں دیں اور روح القدس کے ذریعے اس کی تائید کی۔ (وَآتَيْنَا عِيسَى ابْنَ مَرْيَمَ الْبَيِّنَاتِ وَأَيَّدْنَاهُ بِرُوحِ الْقُدُسِ) 2:87; 2:253
- تاکہ وہ قیامت کے دن ان کے درمیان فیصلہ کرے جس چیز میں وہ اختلاف کرتے تھے۔ (لَيَحْكُمُ بَيْنَهُمْ يَوْمَ الْقِيَامَةِ فِيمَا كَانُوا فِيهِ) 16:124; 22:69
- ہم نے اس کے اوپر کو نیچے کر دیا اور اس پر پکی ہوئی مٹی کے پتھر برسائے۔ (جَعَلْنَا عَالِيَهَا سَافِلَهَا وَأَمْطَرْنَا عَلَيْهَا حِجَارَةً مِّن سِجِّيلٍ) 11:82; 15:74
- ان کے لیے یکساں ہے، خواہ تم انہیں ڈراؤ یا نہ ڈراؤ، وہ ایمان نہیں لائیں گے۔ (سَوَاءٌ عَلَيْهِمْ أَأَنذَرْتَهُمْ أَمْ لَمْ تُنذِرْهُمْ لَا يُؤْمِنُونَ) 2:6; 36:10
- لوگوں کو چھوڑ کر، تو موت کی تمنا کرو اگر تم سچے ہو۔ (مِّن دُونِ النَّاسِ فَتَمَنَّوُا الْمَوْتَ إِن كُنتُمْ صَادِقِينَ) 2:94; 62:6
- اللہ کی عبادت کرو، اس کے سوا تمہارا کوئی معبود نہیں، کیا تم ڈرتے نہیں؟ (اللَّهَ مَا لَكُم مِّنْ إِلَهٍ غَيْرُهُ أَفَلَا تَتَّقُونَ) 23:23; 23:32
- اور اگر ہم تجھے وہ کچھ دکھا دیں جس کا ہم ان سے وعدہ کر رہے ہیں یا تجھے وفات دے دیں، تو ہماری ہی طرف ان کی بازگشت ہے... (وَإِمَّا نُرِيَنَّكَ بَعْضَ الَّذِي نَعِدُهُمْ أَوْ نَتَوَفَّيَنَّكَ فَإِلَيْنَا) 10:46; 40:77
- انہوں نے کہا: "کیا جب ہم مر کر مٹی اور ہڈیاں ہو جائیں گے تو کیا ہم واقعی اٹھائے جائیں گے؟" (قَالُوا أَإِذَا مِتْنَا وَكُنَّا تُرَابًا وَعِظَامًا أَإِنَّا لَمَبْعُوثُونَ) 23:82; 56:47
- بے شک فضل اللہ کے ہاتھ میں ہے، وہ جسے چاہے عطا کرتا ہے، اور اللہ... (إِنَّ الْفَضْلَ بِيَدِ اللَّهِ يُؤْتِيهِ مَن يَشَاءُ وَاللَّهُ) 3:73; 57:29
- اس کی طرف جو پوشیدہ اور ظاہر کا جاننے والا ہے، پھر وہ تمہیں بتائے گا جو تم کرتے تھے۔ (إِلَى عَالِمِ الْغَيْبِ وَالشَّهَادَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ) 9:105; 62:8
- اے ایمان والو! اللہ کا احسان یاد کرو جو اس نے تم پر کیا، جب... (يَا أَيُّهَا الَّذِينَ آمَنُوا اذْكُرُوا نِعْمَتَ اللَّهِ عَلَيْكُمْ إِذْ) 5:11; 33:9
- اور ہم نے تم سے پہلے بھی رسولوں کو مردوں ہی میں سے بھیجا، جن کی طرف وحی کرتے تھے۔ (وَمَا أَرْسَلْنَا مِن قَبْلِكَ إِلَّا رِجَالًا نُّوحِي إِلَيْهِم) 12:109; 16:43
- وہ اس کے گناہوں کو معاف کر دے گا اور اسے جنتوں میں داخل کرے گا جن کے نیچے نہریں بہتی ہیں۔ (يُكَفِّرْ عَنْهُ سَيِّئَاتِهِ وَيُدْخِلْهُ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا) 64:9; 66:8
- بیمار ہو یا سفر میں ہو، تو دوسرے دنوں کی گنتی (پوری کرے)۔ (مَّرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِّنْ أَيَّامٍ أُخَرَ) 2:184; 2:185
- وہ محض گمان کی پیروی کرتے ہیں اور محض اٹکل سے کام لیتے ہیں۔ (إِن يَتَّبِعُونَ إِلَّا الظَّنَّ وَإِنْ هُمْ إِلَّا يَخْرُصُونَ) 6:116; 10:66
- یقیناً تمہارے لیے رسول اللہ میں بہترین نمونہ ہے، اس شخص کے لیے جو اللہ اور آخرت کا امیدوار ہو۔ (أُسْوَةٌ حَسَنَةٌ لِّمَن كَانَ يَرْجُو اللَّهَ وَالْيَوْمَ الْآخِرَ) 33:21; 60:6
- اور ہم نے آسمانوں اور زمین اور ان کے درمیان کی چیزوں کو حق کے ساتھ پیدا کیا۔ (وَمَا خَلَقْنَا السَّمَاوَاتِ وَالْأَرْضَ وَمَا بَيْنَهُمَا إِلَّا بِالْحَقِّ) 15:85; 46:3
- اپنا ہاتھ اپنی جیب میں ڈال، وہ بغیر کسی عیب کے سفید نکلے گا۔ (يَدَكَ فِي جَيْبِكَ تَخْرُجْ بَيْضَاءَ مِنْ غَيْرِ سُوءٍ) 27:12; 28:32
- وہ اپنی رحمت کو جس پر چاہے مخصوص کر لیتا ہے، اور اللہ بڑے فضل والا ہے۔ (يَخْتَصُّ بِرَحْمَتِهِ مَن يَشَاءُ وَاللَّهُ ذُو الْفَضْلِ الْعَظِيمِ) 2:105; 3:74
- کیا تم نہیں جانتے کہ اللہ ہی کے لیے آسمانوں اور زمین کی بادشاہت ہے؟ (أَلَمْ تَعْلَمْ أَنَّ اللَّهَ لَهُ مُلْكُ السَّمَاوَاتِ وَالْأَرْضِ) 2:107; 5:40
- اور جو بھلائی تم اپنے لیے آگے بھیجو گے، اسے اللہ کے پاس پاؤ گے۔ (وَمَا تُقَدِّمُوا لِأَنفُسِكُم مِّنْ خَيْرٍ تَجِدُوهُ عِندَ اللَّهِ) 2:110; 73:20
- اور تم جہاں سے بھی نکلو، اپنا رخ مسجد حرام کی طرف کرو۔ (وَمِنْ حَيْثُ خَرَجْتَ فَوَلِّ وَجْهَكَ شَطْرَ الْمَسْجِدِ الْحَرَامِ) 2:149; 2:150
- ان سے پہلے بھی یہ حال ہو چکا، اور تم اللہ کی سنت میں کوئی تبدیلی نہیں پاؤ گے۔ (خَلَوْا مِن قَبْلُ وَلَن تَجِدَ لِسُنَّةِ اللَّهِ تَبْدِيلًا) 33:62; 48:23
- وہ جس کے لیے آسمانوں اور زمین میں جو کچھ ہے سب ہے۔ (الَّذِي لَهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ) 34:1; 42:53
- اور کوئی عورت حاملہ نہیں ہوتی اور نہ بچہ جنتی ہے مگر اس کے علم سے۔ (وَمَا تَحْمِلُ مِنْ أُنثَى وَلَا تَضَعُ إِلَّا بِعِلْمِهِ) 35:11; 41:47
- رات کو اور اس نے سورج اور چاند کو مسخر کیا، ہر ایک ایک مقررہ مدت تک چل رہا ہے۔ (اللَّيْلِ وَسَخَّرَ الشَّمْسَ وَالْقَمَرَ كُلٌّ يَجْرِي لِأَجَلٍ مُّسَمًّى) 35:13; 39:5
- ان کے نیچے نہریں بہتی ہیں، وہاں وہ ہمیشہ رہیں گے، اور یہ ... کا صلہ ہے۔ (تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا وَذَلِكَ جَزَاءُ) 5:85; 20:76
- اس نے کہا: "نہیں، بلکہ تمہارے نفوس نے تمہیں ایک معاملہ زیب دیا ہے، پس صبر جمیل ہے۔" (قَالَ بَلْ سَوَّلَتْ لَكُمْ أَنفُسُكُمْ أَمْرًا فَصَبْرٌ جَمِيلٌ) 12:18; 12:83
- جو کچھ آسمانوں میں ہے اور جو کچھ زمین میں ہے، اور اللہ... (مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَأَنَّ اللَّهَ) 5:97; 22:64
- اور ان کے پاس جو رسول بھی آیا، وہ اس کا مذاق اڑاتے رہے۔ (وَمَا يَأْتِيهِم مِّن رَّسُولٍ إِلَّا كَانُوا بِهِ يَسْتَهْزِئُونَ) 15:11; 36:30
- انہوں نے کہا: "اے موسیٰ! یا تو تم ڈالو یا ہم ڈالنے والے ہیں؟" (قَالُوا يَامُوسَى إِمَّا أَن تُلْقِيَ وَإِمَّا أَن نَّكُونَ) 7:115; 20:65
- وہ تمہیں موت دیتا ہے، اور تم میں سے کوئی انتہائی ذلیل عمر کی طرف لوٹا دیا جاتا ہے، تاکہ... (يَتَوَفَّاكُمْ وَمِنكُم مَّن يُرَدُّ إِلَى أَرْذَلِ الْعُمُرِ لِكَيْ) 16:70; 22:5
- ان کے لیے ان کے رب کے پاس جنتیں ہیں جن کے نیچے نہریں بہتی ہیں، وہاں وہ ہمیشہ رہیں گے۔ (رَبِّهِمْ جَنَّاتٌ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا) 3:15; 3:136
- اور ہم نے ان کے دلوں پر پردے ڈال دیے تاکہ وہ اسے نہ سمجھیں، اور ان کے کانوں میں... (وَجَعَلْنَا عَلَى قُلُوبِهِمْ أَكِنَّةً أَن يَفْقَهُوهُ وَفِي آذَانِهِمْ) 17:46; 18:57
- بے شک اللہ کا وعدہ سچا ہے، لیکن ان میں اکثر جانتے نہیں۔ (إِنَّ وَعْدَ اللَّهِ حَقٌّ وَلَكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ) 10:55; 28:13
- یہ اس لیے کہ انہوں نے اللہ اور اس کے رسول کی مخالفت کی، اور جو اللہ کی مخالفت کرے... (ذَلِكَ بِأَنَّهُمْ شَاقُّوا اللَّهَ وَرَسُولَهُ وَمَن يُشَاقِقِ اللَّهَ) 8:13; 59:4
- اور جس دن وہ انہیں پکارے گا اور کہے گا: "میرے وہ شریک کہاں ہیں جنہیں تم گمان کرتے تھے؟" (وَيَوْمَ يُنَادِيهِمْ فَيَقُولُ أَيْنَ شُرَكَائِيَ الَّذِينَ كُنتُمْ تَزْعُمُونَ) 28:62; 28:74
- کیا انہوں نے نہیں دیکھا کہ اللہ جس نے آسمانوں اور زمین کو پیدا کیا...؟ (أَوَلَمْ يَرَوْا أَنَّ اللَّهَ الَّذِي خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ) 17:99; 46:33
- جس نے تمہیں مٹی سے پھر نطفہ سے پھر... پیدا کیا۔ (بِالَّذِي خَلَقَكَ مِن تُرَابٍ ثُمَّ مِن نُّطْفَةٍ ثُمَّ) 18:37; 40:67
- وہ کہیں گے: "اے ہمارے رب! کیوں تو نے ہماری طرف کوئی رسول نہیں بھیجا تاکہ ہم تیری آیات کی پیروی کرتے؟" (لَقَالُوا رَبَّنَا لَوْلَا أَرْسَلْتَ إِلَيْنَا رَسُولًا فَنَتَّبِعَ آيَاتِكَ) 20:134; 28:47
- پھر ان کا لوٹنا ان کے رب ہی کی طرف ہے، پھر وہ انہیں بتائے گا جو وہ کرتے تھے۔ (ثُمَّ إِلَى رَبِّهِم مَّرْجِعُهُمْ فَيُنَبِّئُهُم بِمَا كَانُوا يَعْمَلُونَ) 6:108; 39:7
- انہیں اس کا کوئی علم نہیں، وہ محض... (مَّا لَهُم بِذَلِكَ مِنْ عِلْمٍ إِنْ هُمْ إِلَّا) 43:20; 45:24
- ہم نے اپنے باپ دادا کو ایک طریقے پر پایا اور ہم انہی کے نقش قدم پر چل رہے ہیں۔ (إِنَّا وَجَدْنَا آبَاءَنَا عَلَى أُمَّةٍ وَإِنَّا عَلَى آثَارِهِم) 43:22; 43:23
- جنہیں کتاب دی گئی، انہوں نے اس کے بعد ہی اختلاف کیا جب ان کے پاس علم آیا... (الَّذِينَ أُوتُوا الْكِتَابَ إِلَّا مِن بَعْدِ مَا جَاءَهُمُ) 3:19; 98:4
- اور جب ابراہیم نے کہا: "اے میرے رب! اس شہر کو امن والا بنا۔" (وَإِذْ قَالَ إِبْرَاهِيمُ رَبِّ اجْعَلْ هَذَا بَلَدًا آمِنًا) 2:126; 14:35
- اور اس نے تمہیں کان، آنکھیں اور دل دیے، مگر تم بہت کم شکر کرتے ہو۔ (وَجَعَلَ لَكُمُ السَّمْعَ وَالْأَبْصَارَ وَالْأَفْئِدَةَ قَلِيلًا مَّا تَشْكُرُونَ) 32:9; 67:23
- جو لوگ اللہ کی آیات کے بارے میں بغیر کسی دلیل کے جھگڑتے ہیں جو ان کے پاس آئی ہو۔ (الَّذِينَ يُجَادِلُونَ فِي آيَاتِ اللَّهِ بِغَيْرِ سُلْطَانٍ أَتَاهُمْ) 40:35; 40:56
- پس تم ابراہیم کی ملت کی پیروی کرو جو یکسو تھے اور وہ مشرکوں میں سے نہ تھے۔ (فَاتَّبِعُوا مِلَّةَ إِبْرَاهِيمَ حَنِيفًا وَمَا كَانَ مِنَ الْمُشْرِكِينَ) 3:95; 16:123
- اور جب ہم نے تمہیں فرعون کے لوگوں سے نجات دی جو تمہیں سخت عذاب دیتے تھے۔ (وَإِذْ أَنجَيْنَاكُم مِّنْ آلِ فِرْعَوْنَ يَسُومُونَكُمْ سُوءَ الْعَذَابِ) 7:141; 14:6
- یہی سیدھا دین ہے، لیکن اکثر لوگ نہیں جانتے۔ (ذَلِكَ الدِّينُ الْقَيِّمُ وَلَكِنَّ أَكْثَرَ النَّاسِ لَا يَعْلَمُونَ) 12:40; 30:30
- کیا تم نے نہیں دیکھا کہ اللہ نے تمہارے لیے زمین کی چیزوں کو مسخر کر دیا؟ (أَلَمْ تَرَ أَنَّ اللَّهَ سَخَّرَ لَكُم مَّا فِي) 22:65; 31:20
- کافروں نے کہا: "یہ تو کھلا جادو ہے۔" (لَقَالَ الَّذِينَ كَفَرُوا إِنْ هَذَا إِلَّا سِحْرٌ مُّبِينٌ) 6:7; 11:7
- اور جب ان کے سامنے ہماری واضح آیات پڑھی جاتی ہیں تو کافر کہتے ہیں... (وَإِذَا تُتْلَى عَلَيْهِمْ آيَاتُنَا بَيِّنَاتٍ قَالَ الَّذِينَ كَفَرُوا) 19:73; 46:7
- ہمیشگی والی جنتیں جن کے نیچے نہریں بہتی ہیں، وہاں وہ ہمیشہ رہیں گے۔ (جَنَّاتُ عَدْنٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا) 20:76; 98:8
- جو چاہتا ہے، بے شک اللہ ہر چیز پر قادر ہے۔ (مَا يَشَاءُ إِنَّ اللَّهَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ) 24:45; 35:1
- تاکہ وہ تمہارے گناہ معاف کرے اور تمہیں ایک مقررہ مدت تک مہلت دے۔ (لِيَغْفِرَ لَكُم مِّن ذُنُوبِكُمْ وَيُؤَخِّرَكُمْ إِلَى أَجَلٍ مُّسَمًّى) 14:10; 71:4
- تم چاہتے ہو کہ ہمیں اس سے روک دو جس کی ہمارے باپ دادا عبادت کرتے تھے۔ (تُرِيدُونَ أَن تَصُدُّونَا عَمَّا كَانَ يَعْبُدُ آبَاؤُنَا) 14:10; 34:43
- اور جب تمہارے رب نے فرشتوں سے کہا: "میں مٹی سے ایک بشر پیدا کرنے والا ہوں۔" (وَإِذْ قَالَ رَبُّكَ لِلْمَلَائِكَةِ إِنِّي خَالِقٌ بَشَرًا مِّن) 15:28; 38:71
- اور وہی ہے جو ہواؤں کو اپنی رحمت سے پہلے خوشخبری بنا کر بھیجتا ہے۔ (وَهُوَ الَّذِي يُرْسِلُ الرِّيَاحَ بُشْرًا بَيْنَ يَدَيْ رَحْمَتِهِ) 7:57; 25:48
- کہہ دو: "زمین میں چلو پھرو اور دیکھو کہ ... کا انجام کیسا ہوا۔" (قُلْ سِيرُوا فِي الْأَرْضِ فَانظُرُوا كَيْفَ كَانَ عَاقِبَةُ) 27:69; 30:42
- بے شک آسمانوں اور زمین کی پیدائش میں اور رات اور دن کے بدلنے میں (نشانیاں ہیں)۔ (إِنَّ فِي خَلْقِ السَّمَاوَاتِ وَالْأَرْضِ وَاخْتِلَافِ اللَّيْلِ وَالنَّهَارِ) 2:164; 3:190
- کون ہے جو اللہ کو اچھا قرض دے کہ وہ اسے کئی گنا بڑھا دے؟ (مَّن ذَا الَّذِي يُقْرِضُ اللَّهَ قَرْضًا حَسَنًا فَيُضَاعِفَهُ) 2:245; 57:11
- پس تم ان کے درمیان اس کے مطابق فیصلہ کرو جو اللہ نے نازل کیا اور ان کی خواہشات کی پیروی نہ کرو۔ (فَاحْكُم بَيْنَهُم بِمَا أَنزَلَ اللَّهُ وَلَا تَتَّبِعْ أَهْوَاءَهُمْ) 5:48; 5:49
- کیا وہ اس کے سوا کسی اور کا انتظار کر رہے ہیں کہ ان کے پاس فرشتے آئیں یا تمہارا رب آئے...؟ (هَلْ يَنظُرُونَ إِلَّا أَن تَأْتِيَهُمُ الْمَلَائِكَةُ أَوْ يَأْتِيَ) 6:158; 16:33
- بے شک جو لوگ اللہ پر جھوٹ باندھتے ہیں وہ کبھی فلاح نہیں پائیں گے۔ (إِنَّ الَّذِينَ يَفْتَرُونَ عَلَى اللَّهِ الْكَذِبَ لَا يُفْلِحُونَ) 10:69; 16:116
- جیسا کہ فرعون والوں اور ان سے پہلے والوں کا حال تھا، انہوں نے ہماری آیات کو جھٹلایا۔ (كَدَأْبِ آلِ فِرْعَوْنَ وَالَّذِينَ مِن قَبْلِهِمْ كَذَّبُوا بِآيَاتِنَا) 3:11; 8:54
- اور ایمان لانے والوں کو جو نیک عمل کرتے ہیں، خوشخبری دے دو کہ ان کے لیے بڑا اجر ہے۔ (وَيُبَشِّرُ الْمُؤْمِنِينَ الَّذِينَ يَعْمَلُونَ الصَّالِحَاتِ أَنَّ لَهُمْ أَجْرًا) 17:9; 18:2
- اللہ اپنے بندوں میں سے جسے چاہے رزق کشادہ کرتا ہے اور جسے چاہے تنگ کرتا ہے۔ (اللَّهَ يَبْسُطُ الرِّزْقَ لِمَن يَشَاءُ مِنْ عِبَادِهِ وَيَقْدِرُ) 28:82; 29:62
- اور تم اس کی طرف لوٹائے جاؤ گے جو پوشیدہ اور ظاہر کا جاننے والا ہے، پھر وہ تمہیں بتائے گا جو تم کرتے تھے۔ (وَسَتُرَدُّونَ إِلَى عَالِمِ الْغَيْبِ وَالشَّهَادَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ) 9:105; 62:8
- اور رشتہ دار آپس میں ایک دوسرے کے زیادہ حقدار ہیں اللہ کی کتاب میں۔ (وَأُولُو الْأَرْحَامِ بَعْضُهُمْ أَوْلَى بِبَعْضٍ فِي كِتَابِ اللَّهِ) 8:75; 33:6
cmds - Commands, Exhortations, Prohibitions, Instructions
- fard / wajib (فرض / واجب) — فرض / واجب (کرنا ضروری ہے؛ چھوڑنا گناہ)
- mustahabb / mandub (مستحب / مندوب) — مستحب / مندوب (کرنے سے ثواب، نہ کرنے سے گناہ نہیں)
- mubah (مباح) — مباح (نہ ثواب نہ گناہ)
- makruh (مكروه) — مکروہ (ناپسندیدہ، کرنے سے گناہ نہیں مگر بہتر نہیں)
- haram (حرام) — حرام (کرنا گناہ)
- halal (حلال، جائز / قانونی) — مباح اور مستحب دونوں کو شامل ہے — ہر وہ چیز جو حرام نہیں
- صرف اللہ کی عبادت کرو اور اسی سے مدد مانگو۔ 1:5
- صرف اللہ کی عبادت کرو 2:21
- اللہ کے ساتھ کسی کو شریک نہ کرو 2:22
- اللہ وہ ہے جو معاف کرتا ہے (توبہ قبول کرتا ہے)، اس نے آدم (عَلَيْهِ ٱلسَّلَامُ) کی توبہ قبول کی۔ 2:37
- حق کو باطل کے ساتھ نہ ملاؤ اور حق کو چھپاؤ نہیں۔ 2:42
- نماز قائم کرو اور زکوٰۃ دو۔ 2:43
- دوسروں کو نیکی کا حکم دینے سے پہلے خود اس پر عمل کرو 2:44
- اپنے تمام معاملات میں اللہ سے مدد مانگو 2:45
- فساد میں ملوث نہ ہو اور نہ اسے پھیلاؤ 2:60
- لوگوں کو عبادت گاہوں میں جانے سے مت روکو 2:114
- مسجد کی حرمت کا احترام کرو۔ اپنی نماز کی جگہوں کو پاک اور صاف رکھو 2:125
- اللہ کو یاد کرو (نماز، تسبیح وغیرہ سے) اور وہ تمہیں یاد کرے گا، اور اس کا شکر ادا کرو۔ 2:152
- مصیبت میں صبر کرو 2:153
- شیطان کے قدموں پر نہ چلو جو کھلا دشمن ہے۔ 2:168
- کسی کی اندھی تقلید نہ کرو 2:170
- تمام امانتوں کو نبھاؤ اور پورا کرو۔ اپنے دینی فرائض اخلاص کے ساتھ ادا کرو۔ اپنی قسموں اور عہدوں کو پورا کرو۔ وعدے پورے کرو، خاص طور پر اللہ سے کیے گئے وعدے۔ ضرورت مندوں کی مدد کرو اور مشکلات کو دور کرو۔ ان گناہوں سے بچو جو اللہ کی ناراضی کا سبب بنتے ہیں۔ تکبر تمہیں ظلم کی طرف نہ لے جائے 2:177
- قصاص (سزا میں برابری کا قانون) میں تمہارے لیے زندگی ہے۔ 2:179
- رمضان کے مہینے میں روزے رکھو۔ مقررہ روزے رکھو تاکہ متقی بن جاؤ۔ 2:183
- قرآن کو ہدایت کا آخری ذریعہ سمجھو 2:185
- ایک دوسرے کا مال ناحق مت کھاؤ اور نہ حاکموں (ججوں) کو رشوت دو (اپنے مقدمات پیش کرنے سے پہلے)۔ 2:188
