- یتیموں کی حفاظت کرو۔ یتیموں کے بارے میں، ان کے مال میں دیانت داری سے کام کرو اور ان کا مال مت کھاؤ۔ 2:220
- توبہ کرو اور اللہ سے معافی مانگو۔ حیض کے دوران جماع نہ کرو۔ پاکیزگی (جسمانی اور روحانی دونوں) کو برقرار رکھو 2:222
- اپنے خاندان کے تئیں اپنی ذمہ داریاں پوری کرو 2:233
