- شیطان تمہیں فقیری سے ڈراتا ہے اور تمہیں فحاشی (برے کام، زنا، گناہ) کا حکم دیتا ہے۔ 2:268
- ضرورت مندوں کو تلاش کرو اور ان کی مدد کرو 2:273
