- یتیموں کو ان کا مال دو اور (اپنے) برے مال کو (ان کے) اچھے مال سے نہ بدلو اور ان کا مال اپنے مال میں ملا کر مت کھاؤ۔ 4:2
- جن عورتوں سے تم نکاح کرو انہیں ان کا مہر (وہ لازمی نکاح کا تحفہ جو شوہر بیوی کو نکاح کے وقت دیتا ہے) خوش دلی سے دو۔ 4:4
