- وراثت کے احکام کی پابندی کرو 4:11
- عورتوں کو ان کی مرضی کے خلاف وراثت میں لینا حرام ہے، اور تمہیں ان سے سختی سے پیش نہیں آنا چاہیے۔ ان کے ساتھ (بیویوں کے ساتھ) عزت کے ساتھ رہو۔ عورتوں کے حقوق کا احترام اور پاسداری کرو۔ اپنی بیوی کے ساتھ حسن سلوک اور رحم کرو۔ عورتوں کے ساتھ عزت اور انصاف کے ساتھ پیش آؤ 4:19
- ان لوگوں سے نکاح نہ کرو جو تمہارے خونی رشتہ دار ہیں 4:23
