- مرد عورتوں کے سرپرست اور نگران ہیں، کیونکہ اللہ نے بعض کو بعض پر فضیلت دی ہے اور اس لیے کہ وہ اپنے مال سے خرچ کرتے ہیں (ان کی کفالت کے لیے)۔ مرد خاندان کا محافظ اور کفیل ہے 4:34
- اللہ کی عبادت کرو اور اس کے ساتھ کسی کو شریک نہ کرو، والدین، رشتہ داروں، یتیموں، مسکینوں، پڑوسی، ساتھی، راہگیر، اور غلاموں کے ساتھ حسن سلوک کرو۔ اللہ مغرور اور شیخی بازوں کو پسند نہیں کرتا۔ دوسروں کے ساتھ اچھا برتاؤ کرو۔ کمزوروں پر رحم کرو۔ رشتے داریاں نبھاؤ اور رشتہ داروں کی عزت کرو۔ 4:36
- کنجوس مت بنو 4:37
- اللہ اس بات کو معاف نہیں کرتا کہ اس کے ساتھ شریک کیا جائے، اور اس کے سوا جسے چاہے معاف کر دیتا ہے۔ 4:48
- دوسروں سے حسد نہ کرو 4:54
