- اللہ اور اس کے رسول کی اطاعت کرو۔ اپنے درمیان اہل اختیار کا احترام کرو 4:59
- کمزوروں اور محتاجوں پر ظلم نہ کرو 4:75
- تمہیں جو بھی بھلائی پہنچتی ہے وہ اللہ کی طرف سے ہے اور جو برائی پہنچتی ہے وہ تمہاری اپنی طرف سے ہے۔ 4:79
- جو رسول (محمد ﷺ) کی اطاعت کرتا ہے اس نے اللہ کی اطاعت کی۔ 4:80
- جو کسی نیک کام کی سفارش کرے اسے اس کا ثواب ملے گا اور جو برے کام کی سفارش کرے اسے اس کا بوجھ ملے گا۔ 4:85
- کسی مومن کے لیے یہ مناسب نہیں کہ وہ کسی دوسرے مومن کو قتل کرے، سوائے خطا کے۔ 4:92
- جو کسی مومن کو جان بوجھ کر قتل کرے اس کی سزا جہنم ہے جس میں وہ ہمیشہ رہے گا۔ اس پر اللہ کا غضب اور لعنت ہے اور اس کے لیے بڑا عذاب تیار ہے۔ 4:93
- جو اللہ کی راہ میں ہجرت کرے گا وہ زمین میں بہت سی جائے پناہ اور کشائش پائے گا۔ 4:100
- اپنی نمازوں کا خیال رکھو 4:103
- ان لوگوں کی حمایت یا وکالت نہ کرو جو امانت میں خیانت کرتے ہیں 4:105
- اللہ سے معافی مانگو، یقیناً اللہ بڑا معاف کرنے والا، بڑا رحم فرمانے والا ہے۔ 4:106
- اے ایمان والو! عدل کے ساتھ کھڑے رہو، اللہ کے لیے گواہی دیتے رہو، گو تمہارے اپنے خلاف ہو، یا تمہارے والدین یا رشتہ داروں کے خلاف، خواہ وہ امیر ہو یا غریب۔ عدل میں تاخیر نہ کرو؛ ظلم کو دور کرنے میں فوری عمل کرو 4:135
- منافق اللہ کو دھوکہ دینا چاہتے ہیں، حالانکہ وہی انہیں دھوکہ دیتا ہے۔ 4:142
- منافق جہنم کے سب سے نیچے کے درجے میں ہوں گے، تم ان کا کوئی مددگار نہ پاؤ گے۔ 4:145
- اللہ کو یہ پسند نہیں کہ برائی علانیہ کی جائے، مگر اس شخص کی طرف سے جس پر ظلم ہوا ہو۔ 4:148
- رسولوں کو بشارت دینے والے اور ڈرانے والے بنا کر (بھیجا) تاکہ رسولوں کے (آنے) کے بعد لوگوں کے پاس اللہ کے خلاف کوئی حجت نہ رہے۔ 4:165
- اپنے عہد اور وعدے پورے کرو 5:1
- نیکی اور تقویٰ میں ایک دوسرے کی مدد کرو، گناہ اور ظلم میں مدد نہ کرو 5:2
- مردار، خون اور سور کا گوشت نہ کھاؤ 5:3
- انصاف کرو، دوسروں کی دشمنی اور نفرت تمہیں انصاف سے نہ روکے۔ اپنے معاملات میں منصف اور راست باز رہو۔ جان لو کہ انصاف تقویٰ کے قریب ہے۔ انصاف میں تاخیر نہ کرو؛ ظلم کو دور کرنے میں فوری عمل کرو 5:8
- اللہ کی طرف قربت کے ذرائع تلاش کرو اور اس کی راہ میں جہاں تک ہو سکے جہاد کرو تاکہ کامیاب ہو جاؤ۔ 5:35
- اپنی قسموں اور عہدوں کو پورا کرو 5:89
- شراب اور نشہ آور چیزوں سے بچو۔ نشہ آور چیزوں (ہر قسم کی الکوحل والی مشروبات)، جوئے، بتوں اور فال کے تیروں سے سختی سے بچو، یہ سب شیطانی کاموں میں سے گندگی ہیں۔ 5:90
- جب تم حج یا عمرہ کے لیے احرام کی حالت میں ہو تو شکار نہ کرو۔ 5:95
- ان چیزوں کے بارے میں مت پوچھو جو اگر تم پر واضح کر دی جائیں تو تمہیں تکلیف میں ڈال سکتی ہیں۔ 5:101
- دوسروں کے معبودوں کو گالی نہ دو۔ وہ (کافر) اللہ کے سوا جن کو پوجتے ہیں انہیں گالی نہ دو، ورنہ وہ جہالت کی بنا پر اللہ کو گالی دیں گے۔ 6:108
- اگر تم زمین والوں کی اکثریت کی اطاعت کرو گے تو وہ تمہیں اللہ کی راہ سے بھٹکا دیں گے۔ وہ صرف گمان کی پیروی کرتے ہیں اور وہ صرف جھوٹ بولتے ہیں۔ 6:116
- (اے لوگو!) ہر قسم کے گناہ کو، کھلے اور چھپے، چھوڑ دو۔ 6:120
- (اے ایمان والو!) اس (گوشت) میں سے نہ کھاؤ جس پر (ذبح کرتے وقت) اللہ کا نام نہ لیا گیا ہو۔ 6:121
- اللہ جسے ہدایت دینا چاہتا ہے اس کا سینہ اسلام کے لیے کھول دیتا ہے اور جسے گمراہ کرنا چاہتا ہے اس کا سینہ تنگ اور دبا ہوا کر دیتا ہے۔ 6:125
- خرچ میں اعتدال کرو اور اسراف سے بچو۔ تمام مخلوقات کے حقوق کا خیال رکھو 6:141
- اللہ کے ساتھ کسی کو شریک نہ کرو، والدین کے ساتھ نیک سلوک کرو، اپنی اولاد کو مفلسی کے ڈر سے قتل نہ کرو، بے حیائی کے قریب نہ جاؤ، کسی کو قتل نہ کرو جسے اللہ نے حرام کیا ہے، مگر حق کے ساتھ۔ 6:151
- ایماندار رہو؛ اپنے کسی معاملے میں دھوکہ نہ دو۔ یتیم کے مال کے قریب نہ جاؤ، مگر بہتر کرنے کے لیے، پیمانہ پورا کرو اور تول میں انصاف کرو، جب بات کرو تو سچ بولو، چاہے رشتہ دار ہی کیوں نہ ہو، اور اللہ کے عہد کو پورا کرو۔ 6:152
- سیدھے راستے پر چلو اور (دوسرے) راستوں پر نہ چلو، ورنہ وہ تمہیں اس کی راہ سے جدا کر دیں گے۔ 6:153
- (اے محمد ﷺ) کہہ دو: "میری نماز، میری قربانی، میرا جینا اور میرا مرنا سب اللہ کے لیے ہے، جو تمام جہانوں کا رب ہے۔" 6:162
- متکبر نہ بنو 7:13
- شیطان تمہیں دھوکہ نہ دے۔ 7:27
- (اے محمد ﷺ) کہہ دو: "میرے رب نے عدل کا حکم دیا ہے..." 7:29
- اللہ کی مقرر کردہ حدود کا ہر معاملے میں خیال رکھو۔ قول و فعل میں حد سے تجاوز نہ کرو۔ کھاؤ پیو لیکن اسراف نہ کرو۔ نماز کے وقت اچھے کپڑے پہنو 7:31
- اللہ نے آسمانوں اور زمین کو چھ دنوں میں پیدا کیا، پھر وہ عرش پر جا بیٹھا (جیسا کہ اس کی شان کے لائق ہے)۔ 7:54
- اپنے رب کو عاجزی اور چھپ کر پکارو، وہ حد سے گزرنے والوں کو پسند نہیں کرتا۔ 7:55
- زمین پر اس کی اصلاح کے بعد فساد نہ کرو اور اسے ڈر اور امید کے ساتھ پکارو۔ 7:56
- جن لوگوں نے برائیاں کیں اور پھر اس کے بعد توبہ کی اور ایمان لائے تو یقیناً تمہارا رب اس (توبہ) کے بعد بہت معاف کرنے والا، بہت مہربان ہے۔ 7:153
- (اے محمد ﷺ) کہہ دو: "اے لوگو! میں تم سب کی طرف اللہ کا رسول ہوں..." 7:158
- اور (تمام) اچھے نام اللہ ہی کے ہیں، پس انہی ناموں سے اسے پکارو اور ان لوگوں کو چھوڑ دو جو اس کے ناموں میں کجی پیدا کرتے ہیں... 7:180
- اللہ جسے گمراہ کر دے اسے کوئی ہدایت نہیں دے سکتا اور وہ انہیں ان کی سرکشی میں بھٹکتا چھوڑ دیتا ہے۔ 7:186
- معافی کو اپنا شعار بناؤ، نیکی کا حکم دو اور جاہلوں سے منہ موڑ لو (یعنی انہیں سزا نہ دو)۔ 7:199
- دوسروں کی غلطیوں کو معاف کرو 7:199
- اور اگر شیطان کی طرف سے کوئی وسوسہ تمہیں آئے تو اللہ کی پناہ مانگو، یقیناً وہ سننے والا، جاننے والا ہے۔ 7:200
- ایمان والے تو وہ لوگ ہیں کہ جب اللہ کا ذکر کیا جائے تو ان کے دل ڈر جائیں اور جب اس کی آیات پڑھی جائیں تو ان کے ایمان میں اضافہ ہو جائے... 8:2
- اللہ اور اس کے رسول کے ساتھ خیانت نہ کرو اور نہ اپنی امانتوں میں جان بوجھ کر خیانت کرو (جو تمہیں سونپی گئی ہیں اور جو فرائض اللہ نے تم پر عائد کیے ہیں)۔ 8:27
- اگر تم اللہ کی اطاعت کرو گے اور اس سے ڈرو گے تو وہ تمہیں فرقان (حق و باطل کی تمیز) عطا کرے گا۔ 8:29
- جو لوگ کافر ہیں وہ اپنے مال کو اللہ کی راہ سے روکنے کے لیے خرچ کرتے ہیں اور خرچ کرتے رہیں گے، مگر آخر کار یہ ان کے لیے حسرت بن جائے گا۔ 8:36
- کافروں سے کہہ دو کہ اگر وہ (اپنے کفر سے) باز آ جائیں تو جو کچھ گزر چکا ہے وہ معاف کر دیا جائے گا، ورنہ پچھلی قوموں کی سنت گزر چکی ہے۔ 8:38
- جب تم (دشمن کی) فوج سے دوچار ہو تو ان کے مقابلے میں ثابت قدم رہو اور کامیابی کے لیے اللہ کا (زبان اور دل سے) بکثرت ذکر کرو۔ 8:45
- ان لوگوں کی طرح نہ بنو جو اپنے گھروں سے اکڑ کر اور لوگوں کو دکھاوے کے لیے نکلتے ہیں اور اللہ کی راہ سے روکتے ہیں۔ 8:47
- اللہ کسی قوم کی نعمت کو نہیں بدلتا جب تک کہ وہ اپنی حالت کو خود نہ بدل لیں۔ 8:53
- اللہ کے نزدیک بدترین جاندار وہ ہیں جو کفر کریں۔ 8:55
- اللہ اپنے ایمان لانے والوں کے دلوں کے درمیان محبت اور الفت ڈال دیتا ہے 8:63
- پناہ مانگنے والوں کی حفاظت اور مدد کرو 9:6
- مشرکوں کو یہ حق نہیں کہ وہ اللہ کی مسجدوں کو آباد رکھیں۔ 9:17
- وہ (کافر، یہودی اور عیسائی) چاہتے ہیں کہ اللہ کے نور (جس کے ساتھ محمد ﷺ بھیجے گئے – توحید) کو اپنے منہ سے بجھا دیں، مگر اللہ اپنے نور کو مکمل کیے بغیر نہیں رہنے دے گا، خواہ کافروں کو کتنا ہی برا لگے۔ 9:32
- صدقہ (زکوٰۃ) صرف ان کے لیے ہے: 1) فقراء، 2) مساکین، 3) اس کے جمع کرنے والے، 4) جن کے دل اسلام کی طرف مائل کرنا مقصود ہے، 5) غلاموں کو آزاد کرانے میں، 6) مقروضوں کے لیے، 7) اللہ کی راہ میں (مجاہدین کے لیے)، اور 8) مسافروں کے لیے۔ 9:60
- جو اللہ اور اس کے رسول (ﷺ) کا مخالف ہو اور دشمنی رکھتا ہو، اس کے لیے جہنم کی آگ ہے جس میں وہ ہمیشہ رہے گا۔ یہ بہت بڑی رسوائی ہے۔ 9:63
- منافق مرد اور عورتیں، سب آپس میں ایک ہیں۔ وہ اللہ کو بھول گئے تو اللہ نے بھی انہیں بھلا دیا۔ 9:67
- پاکیزگی کے لیے کوشش کرو۔ مسجد کی حرمت کا احترام کرو 9:108
- نبی اور ایمان والوں کو یہ زیب نہیں دیتا کہ وہ مشرکوں کے لیے مغفرت طلب کریں، اگرچہ وہ رشتہ دار ہی ہوں، جب ان پر واضح ہو گیا کہ وہ دوزخی ہیں (کیونکہ وہ کفر کی حالت میں مر گئے)۔ 9:113
- اس سے بڑا ظالم کون ہے جو اللہ پر جھوٹ باندھے یا اس کی آیات کو جھٹلائے؟ یقیناً مجرم کامیاب نہیں ہوں گے! 10:17
- وہ اللہ کے سوا ان چیزوں کو پوجتے ہیں جو نہ انہیں نقصان پہنچا سکتی ہیں نہ نفع، اور کہتے ہیں: "یہ اللہ کے ہاں ہمارے سفارشی ہیں۔" کہہ دو: "کیا تم اللہ کو وہ چیز بتاتے ہو جو وہ آسمانوں اور زمین میں نہیں جانتا؟" وہ پاک اور بلند ہے اس سے جو وہ شریک کرتے ہیں! 10:18
- برائی کا بدلہ ویسی ہی برائی ہے۔ 10:27
- یہ ہے اللہ، تمہارا حقیقی رب، پھر حق کے بعد گمراہی کے سوا کیا ہے؟ پھر تم کیسے پھیرے جاتے ہو؟ 10:32
- ان میں سے اکثر لوگ محض گمان کی پیروی کرتے ہیں، یقیناً گمان حق کی جگہ کچھ کام نہیں دے سکتا۔ 10:36
- اللہ لوگوں پر کچھ ظلم نہیں کرتا، لیکن لوگ خود اپنے اوپر ظلم کرتے ہیں۔ 10:44
- جان لو کہ اللہ کی نعمت اس سے بہتر ہے جو انسان جمع کر سکتا ہے 10:58
- اللہ کی آیات کو جھٹلانے والوں میں سے نہ بنو، ورنہ تم نقصان اٹھانے والوں میں سے ہو گے۔ 10:95
- اگر اللہ تمہیں کوئی تکلیف پہنچائے تو اس کے سوا کوئی اسے دور نہیں کر سکتا، اور اگر وہ تمہارے لیے بھلائی چاہے تو کوئی اس کے فضل کو ٹال نہیں سکتا، وہ اپنے بندوں میں سے جس کو چاہے اپنا فضل پہنچاتا ہے۔ 10:107
- زمین پر کوئی جاندار ایسا نہیں جس کی روزی اللہ کے ذمے نہ ہو، اور وہ اس کی قرار گاہ اور اس کی امانت گاہ (پیٹ، قبر وغیرہ) کو جانتا ہے۔ 11:6
- اگر ہم انسان کو اپنی رحمت کا مزہ چکھائیں، پھر اسے اس سے چھین لیں تو یہ مایوس اور ناشکرا ہو جاتا ہے۔ 11:9
- جو شخص دنیا کی زندگی اور اس کی زیب و زینت چاہتا ہے، ہم انہیں اس میں ان کے اعمال کا پورا پورا بدلہ دے دیں گے اور انہیں کوئی کمی نہیں ہوگی۔ 11:15
- ہم نے ان پر ظلم نہیں کیا، بلکہ انہوں نے خود اپنے اوپر ظلم کیا۔ پس ان کے وہ معبود جنہیں وہ اللہ کے سوا پکارتے تھے، جب تمہارے رب کا حکم آیا تو ان کے کچھ کام نہ آئے اور انہیں ہلاکت کے سوا کچھ نہ دیا۔ 11:101
- جس دن وہ (قیامت) آئے گی کوئی شخص اللہ کی اجازت کے بغیر بات نہیں کرے گا۔ ان میں سے بعض بدبخت ہوں گے اور (بعض) نیک بخت۔ 11:105
- جو بدبخت ہیں وہ جہنم میں ہوں گے، جہاں وہ چلائیں گے اور کراہیں گے۔ 11:106
- وہ اس میں ہمیشہ رہیں گے جب تک آسمان اور زمین قائم ہیں، مگر جب تک تمہارا رب چاہے، یقیناً تمہارا رب جو چاہتا ہے کرتا ہے۔ 11:107
- اور جو نیک بخت ہیں وہ جنت میں ہوں گے، وہ اس میں ہمیشہ رہیں گے جب تک آسمان اور زمین قائم ہیں، مگر جب تک تمہارا رب چاہے، یہ عطیہ ہے بے انتہا۔ 11:108
- ظالموں کی طرف مائل نہ ہو، ورنہ آگ تمہیں چھو لے گی اور اللہ کے سوا تمہارا کوئی کارساز نہ ہو گا، پھر تمہاری مدد نہیں کی جائے گی۔ 11:113
- دن کے دونوں سروں پر اور رات کے کچھ حصوں میں نماز قائم کرو (یعنی پانچوں نمازیں)۔ نیکیاں برائیاں (چھوٹے گناہ) دور کر دیتی ہیں۔ 11:114
- آسمانوں اور زمین کا غیب اللہ ہی کو معلوم ہے، اور تمام معاملات اسی کی طرف لوٹائے جاتے ہیں (فیصلے کے لیے)۔ 11:123
- حکم اللہ کے سوا کسی کا نہیں، اس نے حکم دیا ہے کہ تم اس کے سوا کسی کی عبادت نہ کرو (توحید)، یہی سیدھا دین ہے، لیکن اکثر لوگ نہیں جانتے۔ 12:40
- اللہ کی رحمت سے کبھی مایوس نہ ہو 12:87
- اور اکثر لوگ ایمان نہیں لائیں گے، خواہ تم کتنا ہی چاہو۔ 12:103
- اور ان میں سے اکثر اللہ پر ایمان نہیں رکھتے مگر اس طرح کہ شرک کرتے ہیں (یعنی مشرک ہیں)۔ 12:106
- یہ (قرآن) گھڑا ہوا قول نہیں بلکہ اس سے پہلے کی کتابوں (تورات، انجیل اور دیگر صحیفوں) کی تصدیق ہے اور ہر چیز کی تفصیل ہے اور ایمان لانے والوں کے لیے ہدایت اور رحمت ہے۔ 12:111
- اللہ جسے چاہتا ہے روزی کشادہ کر دیتا ہے اور (جسے چاہتا ہے) تنگ کر دیتا ہے۔ 13:26
- اللہ کو کثرت سے یاد کرو (ذکر کے ذریعے)۔ جو اللہ پر ایمان رکھتے ہیں ان کے دل اللہ کے ذکر سے مطمئن ہوتے ہیں۔ 13:28
- جو ایمان لاتے ہیں اور نیک عمل کرتے ہیں انہیں خوشی اور سکون ملتا ہے۔ 13:29
- جو لوگ آخرت کے بجائے دنیا کی زندگی کو ترجیح دیتے ہیں اور اللہ کی راہ (اسلام) سے روکتے ہیں اور اس میں کجی چاہتے ہیں، وہ دور دراز کی گمراہی میں ہیں۔ 14:3
- عبادت میں عاجزی اور شکرگزاری کرو 14:7
- جو لوگ اپنے رب کا انکار کرتے ہیں ان کی مثال ایسی ہے جیسے راکھ جس پر طوفانی دن میں تیز ہوا چلے، وہ اپنی کمائی میں سے کچھ بھی حاصل نہ کر سکیں گے۔ 14:18
- اللہ ایمان لانے والوں کو دنیا میں (یعنی وہ صرف اللہ ہی کی عبادت کرتے رہیں گے) اور آخرت میں قول ثابت کے ساتھ مضبوط رکھتا ہے۔ 14:27
- یہ خیال نہ کرو کہ اللہ ظالموں (مشرکین، زیادتی کرنے والوں) کے اعمال سے غافل ہے، وہ انہیں اس دن تک مہلت دے رہا ہے جب آنکھیں خوف سے پھٹی رہ جائیں گی۔ 14:42
- تاکہ اللہ ہر شخص کو اس کی کمائی کا بدلہ دے، یقیناً اللہ حساب میں تیز ہے۔ 14:51
- اور ہم نے انسان کو کھنکھناتی مٹی سے، بگڑی ہوئی کالی مٹی سے پیدا کیا۔ 15:26
- اور جنوں کو ہم نے اس سے پہلے آگ کے شعلے سے پیدا کیا۔ 15:27
- اس (جہنم) کے سات دروازے ہیں، ہر دروازے کے لیے گناہگاروں کا ایک خاص حصہ ہے۔ 15:44
- اس نے انسان کو نطفہ (نر و مادہ کے آمیختہ قطرے) سے پیدا کیا، پھر وہ کھلا مخالف بن جاتا ہے۔ 16:4
- اور چوپایوں کو اس نے تمہارے لیے پیدا کیا، ان میں تمہارے لیے گرمی (گرم کپڑے) اور بہت سے فائدے ہیں اور انہیں تم کھاتے ہو۔ 16:5
- اور (اس نے پیدا کیے) گھوڑے، خچر اور گدھے تاکہ ان پر سوار ہو اور زیب و زینت کے لیے، اور وہ ایسی چیزیں پیدا کرتا ہے جنہیں تم نہیں جانتے۔ 16:8
- وہی ہے جس نے آسمان سے پانی برسایا، جسے تم پیتے ہو اور جس سے درخت اگتے ہیں جن پر تم اپنے جانور چراتے ہو۔ 16:10
- وہی ہے جس نے سمندر کو تمہارے لیے مسخر کیا تاکہ تم اس سے تازہ گوشت (مچھلی) کھاؤ اور اس سے زیورات نکالو جو تم پہنتے ہو۔ 16:14
- اس نے زمین میں پہاڑ گاڑ دیے تاکہ وہ تم کو لے کر ڈگمگائے نہیں اور نہریں اور راستے بنائے تاکہ تم راہ پا سکو۔ 16:15
- کیا وہ جو پیدا کرتا ہے اس جیسا ہو سکتا ہے جو پیدا نہیں کرتا؟ کیا تم غور نہیں کرتے؟ 16:17
- اگر تم اللہ کی نعمتوں کو گننا چاہو تو انہیں شمار نہیں کر سکتے۔ 16:18
- اللہ جانتا ہے جو تم چھپاتے ہو اور جو ظاہر کرتے ہو۔ 16:19
- جنہیں یہ (مشرک) اللہ کے سوا پکارتے ہیں انہوں نے کچھ بھی پیدا نہیں کیا، بلکہ وہ خود پیدا کیے گئے ہیں۔ 16:20
- (وہ) مردہ ہیں، بے جان ہیں اور نہیں جانتے کہ کب اٹھائے جائیں گے۔ 16:21
- جب ہم کسی چیز کا ارادہ کرتے ہیں تو ہمارا قول صرف یہ ہوتا ہے کہ "ہو جا" اور وہ ہو جاتی ہے۔ 16:40
- کیا وہ لوگ جو برے مکر و فریب کرتے ہیں اس بات سے بے خوف ہیں کہ اللہ انہیں زمین میں دھسا نہ دے یا ان پر عذاب ایسی جگہ سے نہ آئے جس کا انہیں گمان بھی نہ ہو؟ 16:45
- تمہارے پاس جو کچھ نعمت اور بھلائی ہے وہ اللہ کی طرف سے ہے، پھر جب تمہیں تکلیف پہنچتی ہے تو تم اسی کو پکارتے ہو۔ 16:53
- پھر جب وہ تم سے تکلیف دور کر دیتا ہے تو تم میں سے ایک گروہ اپنے رب کے ساتھ شرک کرنے لگتا ہے۔ 16:54
- ان چوپایوں میں تمہارے لیے عبرت ہے، ہم تمہیں ان کے پیٹوں میں سے گوبر اور خون کے درمیان سے خالص دودھ پلاتے ہیں جو پینے والوں کو خوشگوار لگتا ہے۔ 16:66
- لہذا اللہ کے لیے مثالیں مت دو (کیونکہ اس کی کوئی مثال نہیں اور نہ وہ کسی سے مشابہ ہے)، یقیناً اللہ جانتا ہے اور تم نہیں جانتے۔ 16:74
- جان لو کہ اللہ نے انسان کو سننے، دیکھنے، عقل اور جذبات دیے تاکہ وہ شکر گزار بنے 16:78
- لالچ اور حرص سے بچو 16:97
- جب تم قرآن پڑھنے لگو تو شیطان، جو مردود (رجم شدہ) ہے، سے اللہ کی پناہ مانگو۔ 16:98
- جان لو کہ جاہلانہ ظلم معاف کر دیا جاتا ہے اگر انسان توبہ کر لے اور اپنی اصلاح کر لے 16:119
- (اے محمد ﷺ) اپنے رب کے راستے (اسلام) کی طرف حکمت اور عمدہ نصیحت کے ساتھ بلاؤ اور ان سے بہترین طریقے سے مناظرہ کرو۔ لوگوں کو اللہ کی راہ کی طرف بلانا حکمت اور نرمی کے ساتھ ہونا چاہیے 16:125
- یقیناً اللہ ان لوگوں کے ساتھ ہے جو اس سے ڈرتے ہیں (اپنا فرض ادا کرتے ہیں) اور جو نیکوکار ہیں۔ 16:128
- یہ قرآن اس چیز کی راہنمائی کرتا ہے جو سب سے زیادہ درست اور سیدھی ہے۔ 17:9
- کوئی کسی دوسرے کا بوجھ (گناہ) نہیں اٹھائے گا۔ 17:15
- جو آخرت کا طالب ہو اور اس کے لیے ایسی کوشش کرے جیسی کوشش اس کے لیے زیب دیتی ہے، اور وہ مومن ہو تو ایسے لوگوں کی کوشش قابل قدر اور قابل شکر ہوگی اور (اللہ کے ہاں) اسے بدلہ ملے گا۔ 17:19
- اپنے والدین کا احترام کرو اور ان کے ساتھ حسن سلوک کرو۔ والدین کے ساتھ نیکی کرو۔ انہیں بیزاری کا لفظ مت کہو۔ اور تمہارے رب نے حکم دیا ہے کہ تم اس کے سوا کسی کی عبادت نہ کرو اور والدین کے ساتھ نیک سلوک کرو۔ اگر ان میں سے کوئی ایک یا دونوں تمہارے پاس بڑھاپے کو پہنچ جائیں تو انہیں "اف" تک نہ کہو اور نہ انہیں جھڑکو اور ان سے تعظیم کی بات کرو۔ 17:23
- اور ان کے لیے عاجزی اور نرمی کا پھیلاؤ اور کہو: "اے میرے رب! ان پر رحم فرما جیسا کہ انہوں نے مجھے بچپن میں پالا تھا۔" 17:24
- یقیناً فضول خرچ لوگ شیطانوں کے بھائی ہیں اور شیطان اپنے رب کا بڑا ناشکرا ہے۔ 17:27
- پیسے فضول خرچ نہ کرو 17:29
- مفلسی کے ڈر سے اپنی اولاد کو قتل نہ کرو 17:31
- زنا نہ کرو۔ شادی کی حرمت کو برقرار رکھو اور زنا سے بچو 17:32
- جب ناپو تو پورا پیمانہ بھرو اور سیدھے ترازو سے تولو، یہ بہتر ہے اور انجام کے اعتبار سے زیادہ اچھا ہے۔ 17:35
- (اے انسان!) جس چیز کا تجھے علم نہیں اس کی پیروی نہ کر (مثلاً کوئی کہے "میں نے دیکھا" حالانکہ اس نے نہیں دیکھا، یا "میں نے سنا" حالانکہ اس نے نہیں سنا)۔ 17:36
- عاجزی اختیار کرو اور تکبر نہ کرو۔ زمین پر اکڑ کر نہ چلو، یقیناً نہ تو زمین کو پھاڑ سکتے ہو اور نہ پہاڑوں کی بلندی کو پہنچ سکتے ہو۔ 17:37
- تمہارا رب تمہیں خوب جانتا ہے، اگر چاہے تو تم پر رحم کرے اور اگر چاہے تو تمہیں عذاب دے۔ 17:54
- جو دنیا میں اندھا ہے (یعنی اللہ کی نشانیوں کو نہیں دیکھتا اور اس پر ایمان نہیں رکھتا) وہ آخرت میں بھی اندھا ہوگا اور راستے سے زیادہ بھٹکا ہوا ہوگا۔ 17:72
- نماز کے مقررہ اوقات کا خیال رکھو 17:78
- ہم نے اس قرآن میں لوگوں کو ہر طرح کی مثالیں بیان کر دی ہیں، مگر اکثر لوگ انکار ہی کرتے ہیں (اور حق کو قبول کرنے سے انکاری ہیں)۔ 17:89
- ہم نے اس قرآن میں لوگوں کو ہر طرح کی مثالیں دے دی ہیں، مگر انسان ہر چیز سے زیادہ جھگڑالو ہے۔ 18:54
- ان کا بدلہ جہنم ہے، کیونکہ انہوں نے کفر کیا اور میری آیات اور میرے رسولوں کا مذاق اڑایا۔ 18:106
- اللہ کی شان اس سے پاک ہے کہ وہ کوئی اولاد رکھے (یہ عیسائیوں کے اس الزام کی طرف اشارہ ہے جو وہ اللہ پر لگاتے ہیں کہ عیسیٰ اللہ کا بیٹا ہے)۔ وہ پاک ہے اور ان کے شرک سے بلند ہے۔ 19:35
- لوگوں سے نرمی سے بات کرو 20:44
- نیکی کرنے میں ایک دوسرے سے مقابلہ کرو 21:90
- لغو باتوں سے بچو 23:3
- اپنی شرمگاہوں کی حفاظت کرو 23:5
- اپنے دلوں کو گناہ کے رجحانات سے بچاؤ 23:97
- دوسروں کو معاف کرو اور ان کی غلطیوں سے درگزر کرو 24:22
- دوسروں کی رازداری کا احترام کرو، خاص طور پر ان کے اپنے گھروں میں۔ پڑوسیوں کے حقوق پورے کرو 24:27
- (مردوں اور عورتوں دونوں کے لیے) نگاہیں نیچی رکھو۔ اپنی شرمگاہوں اور عصمت کی حفاظت کرو۔ 24:30
- لباس اور رویے میں شرم و حیا کا خیال رکھو 24:31
- جان لو کہ اللہ ان لوگوں کو امن و سکون عطا کرتا ہے جو اس کی عبادت کریں اور نیک عمل کریں 24:55
- والدین کے نجی کمرے میں بغیر اجازت کے داخل نہ ہو 24:58
- عاجز اور متواضع بنو 25:63
- جھوٹی گواہی اور دھوکے سے بچو 25:72
- آخرت کے ثواب کے لیے کوشش کرو لیکن دنیا کے معاملات کو نظر انداز نہ کرو 28:77
- اللہ کے ساتھ کسی اور معبود کو نہ پکارو 28:88
- ہم جنس پرستی میں ملوث نہ ہو 29:29
- ہر کام میں عمدگی کے لیے کوشش کرو 29:69
- نماز قائم کرو اور زکوٰۃ دو 31:4
- نیکی کا حکم دو اور برائی سے روکو 31:17
- اپنے رویے میں تکبر سے بچو۔ فضول باتوں میں وقت ضائع کرنے سے بچو 31:18
- اپنی چال اور آواز میں اعتدال رکھو 31:19
- نبی محمد ﷺ کے اسوۂ حسنہ کی پیروی کرو 33:21
- عورتوں کو اپنی زیب و زینت اور آرائش کو ظاہر نہیں کرنا چاہیے 33:33
- ہر حال میں سچ بولو 33:70
- غور و فکر کے ذریعے حکمت اور سمجھ حاصل کرو 38:29
- قرآن کے احکام کی پیروی کرو 39:23
